const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { ethers } = require('ethers');
const Redis = require('ioredis');

const redis = new Redis();
const app = express();

const provider = new ethers.providers.JsonRpcProvider(process.env.RPC_URL);

const CONTRACT_ABI = ['function balanceOf(address) view returns (uint256)', 'function transfer(address,uint256) returns (bool)'];
const CONTRACT_ADDR = process.env.CONTRACT_ADDR;
const contract = new ethers.Contract(CONTRACT_ADDR, CONTRACT_ABI, provider);

const typeDefs = gql`
  type Query {
    tokenBalance(owner: String!): String
    transactionHistory(filter: TransactionFilter!): [Transaction]
  }
  input TransactionFilter {
    fromBlock: Int
    toBlock: Int
    address: String!
    eventSignature: String
  }
  type Transaction {
    hash: String
    from: String
    to: String
    value: String
    blockNumber: Int
  }
`;

async function buildFilterQuery(filter) {
  const baseQuery = {
    address: filter.address,
    fromBlock: filter.fromBlock || 0,
    toBlock: filter.toBlock || 'latest'
  };
  if (filter.eventSignature) {
    baseQuery.topics = [ethers.utils.id(filter.eventSignature)];
  }
  return baseQuery;
}

async function getCachedOrFetch(cacheKey, fetchFn, ttl = 60) {
  const cached = await redis.get(cacheKey);
  if (cached) return JSON.parse(cached);
  const result = await fetchFn();
  await redis.setex(cacheKey, ttl, JSON.stringify(result));
  return result;
}

function buildCacheKey(prefix, params) {
  return `${prefix}:${Object.values(params).join(':')}`;
}

async function resolveTransactionHistory(filter) {
  const cacheKey = buildCacheKey('txhist', filter);
  return getCachedOrFetch(cacheKey, async () => {
    const ethFilter = await buildFilterQuery(filter);
    const logs = await provider.getLogs(ethFilter);
    const transactions = await Promise.all(
      logs.map(async (log) => {
        const tx = await provider.getTransaction(log.transactionHash);
        return {
          hash: tx.hash,
          from: tx.from,
          to: tx.to,
          value: tx.value.toString(),
          blockNumber: tx.blockNumber
        };
      })
    );
    return transactions;
  });
}

const VALID_EVENT_PATTERN = /^[a-zA-Z_][a-zA-Z0-9_]*\([a-zA-Z0-9,_ ]*\)$/;

async function executeSubgraphQuery(address, eventSig) {
  const subgraphUrl = process.env.SUBGRAPH_URL;
  const sanitizedEvent = eventSig && VALID_EVENT_PATTERN.test(eventSig) ? eventSig : null;
  const variables = { fromAddr: address };
  let query;
  if (sanitizedEvent) {
    query = `query($fromAddr: String!) { transfers(where: {from: $fromAddr, event: "${sanitizedEvent}"}) { id from to value } }`;
  } else {
    query = `query($fromAddr: String!) { transfers(where: {from: $fromAddr}) { id from to value } }`;
  }
  const response = await fetch(subgraphUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, variables })
  });
  return response.json();
}

const resolvers = {
  Query: {
    tokenBalance: async (_, { owner }) => {
      if (!ethers.utils.isAddress(owner)) throw new Error('Invalid address');
      const balance = await contract.balanceOf(owner);
      return balance.toString();
    },
    transactionHistory: async (_, { filter }) => {
      if (!ethers.utils.isAddress(filter.address)) throw new Error('Invalid address');
      const onChainData = await resolveTransactionHistory(filter);
      if (filter.eventSignature) {
        const subgraphData = await executeSubgraphQuery(filter.address, filter.eventSignature);
        return mergeResults(onChainData, subgraphData);
      }
      return onChainData;
    }
  }
};

function mergeResults(onChain, subgraph) {
  if (!subgraph || !subgraph.data) return onChain;
  const subTransfers = subgraph.data.transfers || [];
  const merged = [...onChain];
  for (const st of subTransfers) {
    if (!merged.find(m => m.hash === st.id)) {
      merged.push({ hash: st.id, from: st.from, to: st.to, value: st.value, blockNumber: null });
    }
  }
  return merged;
}

const server = new ApolloServer({ typeDefs, resolvers });
server.applyMiddleware({ app });
app.listen(4000);
